export const FRAMEWORK_DESCRIPTIONS: Record<string, { readonly description: string; readonly detailedDescription: string }> = {
  "mbti": { description: "Myers-Briggs personality type — 16 types based on four cognitive preference pairs.", detailedDescription: "The Myers-Briggs Type Indicator classifies personality along four axes: Introversion/Extraversion (energy source), Sensing/Intuition (information gathering), Thinking/Feeling (decision making), and Judging/Perceiving (lifestyle orientation). Each combination produces one of 16 types. In work contexts, MBTI helps predict communication style, decision-making approach, and team dynamics. The types describe preferences, not abilities — an INTJ can socialise and an ESFP can focus alone, but each draws energy differently." },
  "enneagram": { description: "Nine personality types based on core motivations and fears.", detailedDescription: "The Enneagram describes nine interconnected personality types, each driven by a core motivation and a core fear. Unlike trait-based models, it focuses on why people behave as they do rather than how. Type 1 fears being corrupt, Type 5 fears being helpless, Type 8 fears being controlled. Each type has healthy, average, and unhealthy expressions. In professional settings, the Enneagram reveals what drives engagement, what triggers stress, and how people respond under pressure." },
  "disc": { description: "Four behavioural styles — Dominance, Influence, Steadiness, Conscientiousness.", detailedDescription: "DISC measures observable behaviour across two axes: pace (fast vs. measured) and focus (task vs. people). D types are direct and results-driven. I types are enthusiastic and collaborative. S types are patient and supportive. C types are precise and analytical. Most people lead with one or two styles. DISC is widely used in workplace communication because it describes how people act rather than why — making it practical for adapting communication style to your audience." },
  "belbin": { description: "Nine team roles describing how people contribute to group work.", detailedDescription: "Belbin Team Roles identify nine clusters of behaviour that emerge in team settings. Each person typically has a primary role (strongest contribution), one or two secondary roles, and roles they avoid. The nine roles span three categories: thinking roles (Plant, Monitor Evaluator, Specialist), action roles (Shaper, Implementer, Completer-Finisher), and people roles (Co-ordinator, Teamworker, Resource Investigator). Balanced teams need coverage across all three categories." },
  "sdi": { description: "Strength Deployment Inventory — motivational values driving behaviour.", detailedDescription: "The SDI (Strength Deployment Inventory) maps three core motives: concern for people (Blue), concern for performance (Red), and concern for process (Green). Hub blends all three. Unlike behavioural models, SDI focuses on what people value and why they deploy their strengths. Crucially, SDI tracks how motives shift under conflict — a Blue (altruistic) person may shift to Red (assertive) when their values are threatened. This makes it particularly useful for understanding team friction." },
  "bigFive": { description: "Five broad personality dimensions backed by extensive research.", detailedDescription: "The Big Five (OCEAN) is the most empirically validated personality model. It measures Openness to experience, Conscientiousness, Extraversion, Agreeableness, and Neuroticism (emotional reactivity). Each dimension is a spectrum, not a binary. High Openness correlates with creativity and adaptability; high Conscientiousness with reliability and follow-through; high Extraversion with energy in social settings; high Agreeableness with cooperation; low Neuroticism with emotional stability under pressure." },
};

